<?php if(!empty($user['avatar_hash']) && preg_match('/^(?:a_)?[a-f0-9]{32}$/D',$user['avatar_hash']) && preg_match('/^[0-9]{17,20}$/D',$user['discord_user_id']??'')): ?><img class="member-avatar" width="44" height="44" alt="" referrerpolicy="no-referrer" src="https://cdn.discordapp.com/avatars/<?= e($user['discord_user_id']) ?>/<?= e($user['avatar_hash']) ?>.png?size=128"><?php else: ?><span class="member-avatar avatar-fallback" aria-hidden="true"><?= icon('shield') ?></span><?php endif; ?>
